enum class State : std::uint8_t { closed, open, half_open };

bool admit(Breaker& b) {                        // one breaker per dependency
    auto s = b.st.load(std::memory_order_acquire);
    if (s == State::closed) return true;
    if (s == State::open) {
        if (steady_now() - b.opened_at.load(std::memory_order_relaxed) < kCooldown)
            return false;                       // still cooling down
        return b.st.compare_exchange_strong(s, State::half_open);   // one trial call
    }
    return b.half_open_trials.fetch_add(1) < kTrials;               // limited trials
}

