void AsyncBreaker::trip() {                     // runs on the strand
    st_ = State::open;
    cooldown_.expires_after(kOpenDuration);     // the timer owns the recovery clock
    cooldown_.async_wait(boost::asio::bind_executor(strand_, [this](error_code ec) {
        if (!ec) { st_ = State::half_open; }    // operation_aborted is not a failure
    }));
}

